    Promise.all(closing).then(() => { streamsClosed = true }),
    new Promise((resolve) => { closeTimer = setTimeout(resolve, 3000) }),
  ])
  clearTimeout(closeTimer)
  if (!streamsClosed) { state.streamCleanupUnconfirmed = true; failure ??= 'stream cleanup unconfirmed' }
  if (server?.listening) {
    let closed = false
    let serverTimer
    await Promise.race([
      new Promise((resolve) => server.close(() => { closed = true; resolve() })),
      new Promise((resolve) => { serverTimer = setTimeout(resolve, 3000) }),
    ])
    clearTimeout(serverTimer)
    if (!closed) { state.relayCleanupUnconfirmed = true; failure ??= 'relay cleanup unconfirmed' }
  }
  state.remainingStreams = active.size
  if (active.size) failure ??= 'stream cleanup unconfirmed'
  writeFileSync(`${base}/registry-control/install-result.json`, JSON.stringify({ state, failure, result }, null, 2), { flag: 'wx', mode: 0o600 })
  console.log(JSON.stringify({ state, failure, exit: result?.code }, null, 2))
  if (failure) process.exitCode = 1
}
